/**
 * Ring-Pedersen commitments, and the proofs that go with them
 *
 * A Pedersen commitment over an RSA modulus rather than an elliptic curve:
 *
 *     C = s^x * t^r  (mod N)
 *
 * where N is a product of two safe primes held by the VERIFIER, and s lies in
 * the group generated by t.
 *
 * ================ WHY NOT THE ELLIPTIC-CURVE PEDERSEN ================
 *
 * pedersen.js already commits to values, and does it faster. The difference is
 * WHAT CAN BE COMMITTED TO. A curve commitment lives in a group of fixed prime
 * order, so it commits to a scalar modulo that order; asking whether the
 * committed value is SMALL - below 2^256 when the group order is 2^252 - is not
 * a question the structure can express.
 *
 * Ring-Pedersen has no such order. The exponent is an integer, and a proof
 * about its SIZE is possible. That is what range proofs need, and range proofs
 * are what threshold ECDSA is built on.
 *
 * THE MODULUS BELONGS TO THE VERIFIER, and this is the part that looks
 * backwards. In every other commitment here the prover picks the parameters.
 * Here the verifier does, because the hiding property depends on the prover
 * NOT knowing the factorisation - a prover who knew p and q could open a
 * commitment to any value. Each party therefore publishes its own N, s, t and
 * proves they are well formed, and every other party uses those parameters
 * when proving TO it.
 *
 * ==================== WHY THIS FILE IS SEPARATE ====================
 *
 * These are the pieces of threshold ECDSA that are primitives - input to
 * output, checkable in isolation. The protocol they serve is not here: the
 * multiplicative-to-additive conversion and the four rounds of message passing
 * belong in a library that owns the networking and the state.
 *
 * THEY ARE ALSO THE PIECES THAT BROKE. The TSSHOCK attacks of 2021 recovered
 * complete private keys from deployed GG18 implementations, and the flaw was
 * not in Paillier or in the signature scheme. It was in the proofs around
 * them - checks omitted, ranges not enforced, challenges derived from
 * transcripts that a prover could influence. Implementing these carelessly
 * inside a larger protocol is exactly how that happened.
 */

import { safe_prime_task, random_prime_task, mod_inverse, powmod, powmod_ct, powmod_signed_ct, powmod_signed, gcd, jacobi, is_probable_prime,
         require_rng, unit_in, in_range, mod, random_below_biased, random_signed_below, random_unit,
         random_quadratic_residue, crt as crt_general }
    from './commons/primes.js';
import { require_sid, fs_stream, fs_bits, fs_uint, fs_unit } from './commons/zk_bytes.js';
import { finish_task, map_task, done_task, then_task, repeat_task } from './commons/task.js';

/* ---------------- parameter generation ---------------- */

/* safe_prime moved to commons/primes.js - CGGMP21 needs the same search
   for each party's Paillier modulus, and two copies would drift. */


/**
 * Generate a party's Ring-Pedersen parameters.
 *
 * N is a product of two safe primes, t is a random quadratic residue, and
 * s = t^lambda for a secret lambda.
 *
 * THE SECRETS ARE RETURNED and must be kept: lambda is needed to prove the
 * parameters well formed, and the factorisation is needed for the modulus
 * proof. They are never sent.
 *
 * @param  {number}   bits  of N; 2048 minimum for real use
 * @return {{pub: {N, s, t}, sec: {p, q, lambda, phi}}}
 */
/**
 * The parameters, from two primes that already satisfy the constraints.
 *
 * ⭐ SHARED BY keygen AND the old keygen_cb, which otherwise held twenty identical
 *   lines each - jscpd found them. Two copies of a construction is how one
 *   gets a correction and the other does not, and here the two would differ
 *   silently: same shape, different generators, and nothing failing.
 */
function assemble_params(a, b, bits, rng) {
    var N = a.p * b.p;
    var phi = (a.p - 1n) * (b.p - 1n);
    /* the order of the quadratic-residue subgroup */
    var pq = a.q * b.q;

    /*
     * t is a random square, so it generates the QR subgroup;
     * lambda is uniform below its order.
     *
     * ⭐ THE SHARED SAMPLERS: primes.random_quadratic_residue and
     *   random_below_biased. This drew (bits >> 3) + 16 bytes for both - one
     *   byte short of the modulus's width whenever bits is not a multiple of
     *   8 - accepted t = 1 (from tau = +-1), and wrote the square-a-unit loop
     *   a fourth time.
     */
    var t = random_quadratic_residue(N, rng);
    var lambda = random_below_biased(pq, rng);
    /*
     * ⛔ lambda IS THE TRAPDOOR. Anyone who learns it can open any
     *   ring-Pedersen commitment to any value, which is the whole security
     *   assumption of every proof built on these parameters.
     *
     * ⚠ THIS RUNS ONCE PER PARAMETER SET, so an attacker gets one
     *   observation rather than many - a far weaker position than against
     *   RSA decryption. It is still the trapdoor, and the cost of the flat
     *   path is a few percent on a one-off setup.
     */
    var s = powmod_ct(t, lambda, N);

    var out = {
        pub: { N: N, s: s, t: t },
        sec: { p: a.p, q: b.p, lambda: lambda, phi: phi, pq: pq }
    };
    /*
     * ⚠ TWO NAMES FOR ONE THING. paillier, ml_dsa and slh_dsa all return
     * { pk, sk }; this file predates that and returns { pub, sec }. Both are
     * provided and they are THE SAME OBJECTS, not copies. New code should
     * use { pk, sk }.
     */
    out.pk = out.pub;
    out.sk = out.sec;
    return out;
}

/**
 * @param {number}   bits
 * @param {function} [rng]  omitted or null draws fresh ones from the platform
 * @param {function} [onCandidate]  (attempt) -> void
 *
 * `onCandidate` fires per prime candidate. Two safe primes at 1024 bits take
 * around nine seconds and at 2048 bits minutes, and a caller with no output
 * assumes the process has died.
 */
export function keygen(bits, rng, onCandidate, primes) {
    return finish_task(keygen_task(bits, rng, onCandidate, primes));
}

/**
 * keygen as a task (commons/task.js): the two safe-prime searches - all but
 * a few milliseconds of it, 27 seconds at 1024 bits - a candidate a step,
 * so the callback form runs it in slices.
 */
export function keygen_task(bits, rng, onCandidate, primes) {
    var opts_primes = primes;
    if (bits < 512) { throw new Error('ring_pedersen: modulus must be at least 512 bits'); }
    rng = require_rng('ring_pedersen.keygen', rng);
    var half = bits >> 1;

    /*
     * `primes` lets a caller supply the two safe primes as {p, q} pairs.
     * The search is the entire cost and it is a blocking loop - see
     * material.js, which does it while yielding.
     */
    if (opts_primes) {
        var a = opts_primes[0], b = opts_primes[1];
        if (!a || !b || a.p === b.p) {
            throw new Error('ring_pedersen: primes must be two distinct safe primes');
        }
        return done_task(assemble_params(a, b, bits, rng));
    }
    function search() { return safe_prime_task(half, rng, onCandidate); }
    return then_task(search(), function (first) {
        /* a second prime, drawn again while it equals the first */
        return map_task(repeat_task(search, function (second) { return second.p !== first.p; }),
                        function (second) { return assemble_params(first, second, bits, rng); });
    });
}

/**
 * C = s^x * t^r mod N.
 *
 * x MAY BE NEGATIVE, which is the point - the exponent is an integer, not a
 * residue, and range proofs rely on being able to commit to values on both
 * sides of zero.
 */
export function commit(pub, x, r, bits) {
    /*
     * ⛔ THIS IS THE COMMITMENT ITSELF: x is the value it exists to hide and
     *   r is the blinder that hides it. Both were raised through a plain
     *   powmod, whose square-and-multiply time tracks the exponent's Hamming
     *   weight, AND through an inline `x < 0n ?` that branches on the
     *   exponent's SIGN into a path doing an extra inversion. So the timing
     *   of a ring-Pedersen commitment carried both the magnitude profile and
     *   the sign of the value being committed. Measured on the primitive:
     *   2.07 on weight, 1.23 on sign.
     *
     * ⚠ bits IS THE WIDTH OF THE PUBLIC RANGE x AND r WERE SAMPLED FROM, and
     *   callers committing to values wider than pub.N MUST pass it: the
     *   ladder walks exactly the width it is given and powmod_ct throws
     *   rather than truncating. It defaults to the modulus width, which is
     *   right whenever the committed value is reduced mod N.
     */
    var sx = powmod_signed_ct(pub.s, x, pub.N, bits);
    var tr = powmod_signed_ct(pub.t, r, pub.N, bits);
    if (sx === null || tr === null) { throw new Error('ring_pedersen: non-invertible base'); }
    return (sx * tr) % pub.N;
}

/* ---------------- the Fiat-Shamir transcript ---------------- */

/**
 * Derive `count` challenge bits from a transcript.
 *
 * EVERY VALUE THE VERIFIER USES GOES IN. That is not a stylistic point: a
 * challenge derived from a partial transcript lets a prover choose the
 * remaining values after seeing it, and several of the 2021 attacks on
 * deployed threshold ECDSA came down to exactly that.
 *
 * The domain string keeps the two proofs in this file from colliding, and
 * keeps both from colliding with anything else in the library.
 */
/*
 * `sid` BINDS THE PROOF TO ONE RUN.
 *
 * Without it the challenge is a function of the statement alone, so a proof
 * produced in one session verifies in every other session with the same
 * modulus - and in CGGMP21 that means whoever watched one key generation can
 * replay its proofs into the next.
 *
 * The library cannot construct this: session identifier, prover and verifier
 * are the protocol's, not the algebra's. So it is a parameter, absorbed
 * before anything else, and empty by default so existing callers are
 * unaffected.
 */
/*
 * ⚠ v1 OF EVERY TRANSCRIPT IN THIS FILE HASHED mod_bytes(N, N) - which is
 *   N mod N = 0, a run of zero bytes as wide as N. So the challenges bound the
 *   modulus's WIDTH and not its value: in Pi_mod, the proof that N is a
 *   Paillier-Blum modulus, the statement N itself was not in the Fiat-Shamir
 *   hash. (The y_i were still reduced mod N, which is why nothing failed.)
 *   N goes in whole in v2, and the other values reduced mod N as before.
 *
 * The bits, values and large challenges below all come from
 * zk_bytes.fs_stream now; this file had three expanders of its own
 * (challenge_bits, challenge_values, and large_challenge's seed-then-index
 * hash), each framing its input differently.
 */
function prm_bits(pub, A, sid, rounds) {
    var N = pub.N, parts = [N, mod(pub.s, N), mod(pub.t, N)];
    for (var i = 0; i < rounds; i++) { parts.push(mod(A[i], N)); }
    return fs_bits(fs_stream('cryptographic-primitives/ring-pedersen/prm/v2', sid, parts), rounds);
}

/**
 * The cut-and-choose round count, defaulted and checked.
 *
 * Pi_prm and Pi_mod, prover and verifier, each opened with the same four
 * lines - four copies of a SECURITY PARAMETER's default, which is the copy
 * that must never drift: a prover defaulting to 128 against a verifier
 * defaulting to 80 fails every proof, and the other way round accepts weaker
 * ones than intended.
 */
function check_rounds(rounds) {
    if (rounds === undefined) { rounds = 128; }   // 2^-128 soundness: CGGMP24 spec, m = 128
    if (typeof rounds !== 'number' || !(rounds > 0) || (rounds | 0) !== rounds) {
        throw new TypeError('ring_pedersen: rounds must be a positive integer');
    }
    return rounds;
}

/* ---------------- Pi_prm: the parameters are well formed ---------------- */

/**
 * Prove that s lies in the group generated by t.
 *
 * WITHOUT THIS PROOF THE PARAMETERS ARE USELESS. If s is not a power of t, the
 * commitment scheme is not binding: the verifier who chose N can open a
 * commitment to whatever it likes, and every range proof made against these
 * parameters means nothing.
 *
 * It is a cut-and-choose with m rounds, and the soundness is 2^-m - so m is a
 * security parameter, not a tuning knob. CGGMP21 uses 80.
 *
 * @param {function} [rng]  omitted or null draws fresh ones from the platform
 * @return {{A: Array<bigint>, z: Array<bigint>}}
 */
export function prove_params(pub, sec, rng, rounds, sid) {
    require_sid('ring_pedersen', sid);
    rng = require_rng('ring_pedersen.prove_params', rng);
    /*
     * `rounds`, NOT `m`. It used to be `m`, which reads as "message" - a
     * caller passed a Uint8Array, `m || 80` kept it, and every comparison
     * against it silently misbehaved until verify returned false. A false
     * from a verifier looks like a cryptographic failure, not a type error,
     * and that is twenty minutes of looking in the wrong place.
     */
    rounds = check_rounds(rounds);
    var a = [], A = [];
    var i;

    for (i = 0; i < rounds; i++) {
        /* uniform below the group order: primes.random_below_biased, where
           this used to size its draw from N's width, floored */
        var ai = random_below_biased(sec.pq, rng);
        a.push(ai);
        /* ⛔ ai is a fresh Schnorr nonce - leaking it recovers the
           trapdoor from the response. Bounded by sec.pq, which is below
           pub.N, so the modulus-width default is correct here. */
        A.push(powmod_ct(pub.t, ai, pub.N));
    }

    var e = prm_bits(pub, A, sid, rounds);

    var z = [];
    for (i = 0; i < rounds; i++) {
        /* z_i = a_i + e_i * lambda, over the integers modulo the group order */
        z.push(((a[i] + (e[i] ? sec.lambda : 0n)) % sec.pq + sec.pq) % sec.pq);
    }
    return { A: A, z: z };
}

/** @return {boolean} */
export function verify_params(pub, proof, rounds, sid) {
    require_sid('ring_pedersen', sid);
    rounds = check_rounds(rounds);
    if (!proof || !proof.A || proof.A.length !== rounds || proof.z.length !== rounds) {
        return false;
    }
    /* the modulus must be odd and not tiny; a prover choosing N = 1 would
       otherwise satisfy everything below trivially */
    if (pub.N < 3n || (pub.N & 1n) === 0n) { return false; }
    if (gcd(pub.s, pub.N) !== 1n || gcd(pub.t, pub.N) !== 1n) { return false; }

    var i;

    /*
     * THE COMMITMENTS AND RESPONSES MUST BE IN THEIR DOMAINS, which the
     * specification asks for in section 3.6 and this did not check: A_i in
     * Z*_N, z_i in Z_N. A verifier that lets a hostile value through and
     * relies on the arithmetic to reject it is relying on an accident - a
     * non-unit A_i satisfies the relation below in degenerate ways, and a z_i
     * outside the range is a different statement wearing the same bytes.
     */
    for (i = 0; i < rounds; i++) {
        if (typeof proof.A[i] !== 'bigint' || typeof proof.z[i] !== 'bigint') {
            return false;
        }
        if (!unit_in(proof.A[i], pub.N)) { return false; }
        if (proof.z[i] < 0n || proof.z[i] >= pub.N) { return false; }
    }
    var e = prm_bits(pub, proof.A, sid, rounds);

    for (i = 0; i < rounds; i++) {
        /* t^z_i == A_i * s^e_i */
        var lhs = powmod(pub.t, proof.z[i], pub.N);
        var rhs = e[i] ? (proof.A[i] * pub.s) % pub.N : proof.A[i] % pub.N;
        if (lhs !== rhs) { return false; }
    }
    return true;
}

/* ---------------- Pi_mod: N is a Paillier-Blum modulus ---------------- */

/**
 * Prove that N = p*q with p, q prime and both congruent to 3 mod 4, without
 * revealing them.
 *
 * WHY THE SHAPE MATTERS. A modulus that is not a product of exactly two primes
 * breaks the soundness of everything built on it - the paper's argument is
 * that if N has more than two prime factors, the prover can only answer the
 * challenges by luck, with probability 2^-m. And p, q = 3 mod 4 makes -1 a
 * non-residue, which is what lets the fourth-root test below work at all.
 *
 * The protocol: the verifier picks random y, and the prover must exhibit a
 * fourth root of one of {y, -y, w*y, -w*y} together with an N-th root of y.
 * Being able to do both for every challenge requires knowing the
 * factorisation AND requires N to have the claimed shape.
 *
 * @param {function} [rng]  omitted or null draws fresh ones from the platform
 * @return {{w, x: Array, a: Array, b: Array, z: Array}}
 */
export function prove_modulus(N, p, q, rng, rounds, sid) {
    require_sid('ring_pedersen', sid);
    rng = require_rng('ring_pedersen.prove_modulus', rng);
    rounds = check_rounds(rounds);
    if ((p % 4n) !== 3n || (q % 4n) !== 3n) {
        throw new Error('ring_pedersen: primes must be 3 mod 4');
    }
    var phi = (p - 1n) * (q - 1n);
    var Ninv = mod_inverse(N % phi, phi);
    if (Ninv === null) { throw new Error('ring_pedersen: gcd(N, phi) != 1'); }

    /* w is a fixed non-residue with Jacobi symbol 1 */
    /* a random unit (primes.random_unit) until its Jacobi symbol is -1 -
       half of them are, so the bound is a loud failure rather than a limit */
    var w;
    for (var tries = 0; ; tries++) {
        w = random_unit(N, rng);
        if (jacobi(w, N) === -1) { break; }
        if (tries > 10000) { throw new Error('ring_pedersen: could not find a non-residue'); }
    }

    var ys = mod_values(N, w, sid, rounds);

    var x = [], a = [], b = [], z = [];
    for (var i = 0; i < rounds; i++) {
        var y = ys[i];
        /* z_i is the N-th root of y, computable only with phi(N) */
        /* ⛔⛔ Ninv IS DERIVED FROM phi(N). Leaking it recovers phi and so
           factors N - the trapdoor this proof attests to without revealing.
           Ninv is below N, so the modulus-width default is correct. */
        z.push(powmod_ct(y, Ninv, N));

        /* find which of the four candidates is a quartic residue */
        var found = false;
        for (var ai = 0; ai < 2 && !found; ai++) {
            for (var bi = 0; bi < 2 && !found; bi++) {
                var cand = y;
                if (ai) { cand = (N - cand) % N; }
                if (bi) { cand = (cand * w) % N; }
                var root = fourth_root(cand, p, q, N);
                if (root !== null) {
                    a.push(ai); b.push(bi); x.push(root);
                    found = true;
                }
            }
        }
        if (!found) { throw new Error('ring_pedersen: no quartic residue among the four'); }
    }
    return { w: w, x: x, a: a, b: b, z: z };
}

/** @return {boolean} */
export function verify_modulus(N, proof, rounds, sid) {
    require_sid('ring_pedersen', sid);
    rounds = check_rounds(rounds);
    if (!proof || !proof.x || proof.x.length !== rounds) { return false; }

    /* N must be odd, composite, and not a prime power - the paper requires
       all three, and skipping any of them is a soundness hole rather than a
       missing convenience check */
    if (N < 9n || (N & 1n) === 0n) { return false; }
    if (is_probable_prime(N)) { return false; }
    /*
     * ⛔ N = 1 mod 4 (eprint 2024/1950 Protocol 5's first check). Without it a
     *   modulus of THREE primes all = 3 mod 4 (so N = 3 mod 4) passes a round
     *   with probability about 1/2 instead of 1/4 - measured 203 of 400 in
     *   review - so the ell/2 rounds that paper relies on gave 2^-64. Every
     *   Blum modulus p = q = 3 mod 4 satisfies it, so no honest caller is
     *   affected.
     */
    if ((N & 3n) !== 1n) { return false; }

    /*
     * ==================== gcd(w, N) = 1 IS A DISCLOSED VULNERABILITY ====================
     *
     * The 2021 revision of CGGMP said, in Figure 16 page 36:
     *
     *     "N is an odd composite number."
     *
     * The 2024 revision says, in Figure 12 page 31:
     *
     *     "N is an odd composite number and gcd(w, N) = 1."
     *
     * That single conjunct is the whole difference, and DFNS disclosed it on
     * 24 November 2025 as leading to FULL PRIVATE KEY EXTRACTION. The
     * security proof had always assumed the check; the step-by-step
     * description simply never said so, and every implementation that
     * followed the text was missing it.
     *
     * The same revision also tightened w and y_i from Z_N to Z*_N. The y_i
     * here are derived rather than received - mod_values only emits
     * values coprime to N - so that half holds by construction.
     *
     * Everything below is Figure 12's verification list, in its order, and
     * none of it is optional: a verifier that lets a hostile value through
     * and relies on the arithmetic to reject it is relying on an accident.
     */
    if (!unit_in(proof.w, N)) { return false; }
    for (var d = 0; d < rounds; d++) {
        if (typeof proof.x[d] !== 'bigint' || typeof proof.z[d] !== 'bigint') {
            return false;
        }
        if (!unit_in(proof.x[d], N) || !unit_in(proof.z[d], N)) { return false; }
        if (proof.a[d] !== 0 && proof.a[d] !== 1) { return false; }
        if (proof.b[d] !== 0 && proof.b[d] !== 1) { return false; }
    }

    var ys = mod_values(N, proof.w, sid, rounds);

    for (var i = 0; i < rounds; i++) {
        var y = ys[i];
        /* z_i^N == y */
        if (powmod(proof.z[i], N, N) !== y % N) { return false; }

        /* x_i^4 == (-1)^a * w^b * y */
        var expect = y;
        if (proof.a[i]) { expect = (N - expect) % N; }
        if (proof.b[i]) { expect = (expect * proof.w) % N; }
        var x4 = powmod(proof.x[i], 4n, N);
        if (x4 !== expect % N) { return false; }
    }
    return true;
}

/**
 * Pi_mod's challenges y_1 .. y_m: units mod N, derived from the transcript -
 * zk_bytes.fs_unit, so each is uniform over the units other than 1, by the
 * same sampler a prover uses with a real rng.
 */
function mod_values(N, w, sid, count) {
    var read = fs_stream('cryptographic-primitives/ring-pedersen/mod/v2', sid, [N, mod(w, N)]);
    var out = [];
    for (var i = 0; i < count; i++) { out.push(fs_unit(read, N)); }
    return out;
}

/**
 * A fourth root modulo N = p*q, or null if there is none.
 *
 * Both primes are 3 mod 4, so a square root is one exponentiation each side,
 * and CRT combines them. Applying it twice gives the fourth root; the check
 * after each step is what detects that the input was not a residue.
 */
function fourth_root(y, p, q, N) {
    var s1 = sqrt_mod(y, p);
    var s2 = sqrt_mod(y, q);
    if (s1 === null || s2 === null) { return null; }
    var r1 = crt_general([s1, s2], [p, q]);
    if ((r1 * r1) % N !== y % N) { return null; }

    var t1 = sqrt_mod(r1, p);
    var t2 = sqrt_mod(r1, q);
    if (t1 === null || t2 === null) { return null; }
    var r2 = crt_general([t1, t2], [p, q]);
    return powmod(r2, 4n, N) === y % N ? r2 : null;
}

function sqrt_mod(a, p) {
    var r = powmod(((a % p) + p) % p, (p + 1n) / 4n, p);
    return (r * r) % p === ((a % p) + p) % p ? r : null;
}


/* =========================================================================
 * TOUGH primes - Adjedj, Blokh, Couteau, Galansky, Joux, Makriyannis,
 * eprint 2024/1950 section 4.1, "Algorithm 3 / SampleDF".
 * ======================================================================= */

/**
 * The parameters, from two tough primes.
 *
 * ⭐ SHARED BY keygen_rough AND the old keygen_rough_cb, which jscpd found holding
 *   the same thirty-two lines. Two copies of a parameter construction is the
 *   worst kind to duplicate: a divergence gives the same SHAPE with
 *   different generators, so both keep working and neither fails.
 */
/*
 * ⭐ random_square, which drew t here and v in df_from_primes, is
 *   primes.random_quadratic_residue now - the one "random square mod N" in
 *   the library, and the same function assemble_params uses.
 */

function assemble_rough(a, b, rng) {
    var N = a.p * b.p;
    var phi = (a.p - 1n) * (b.p - 1n);
    var pq = ((a.p - 1n) / 2n) * ((b.p - 1n) / 2n);

    /* t is a random square, so it generates QR_N */
    var t = random_quadratic_residue(N, rng);
    var lambda = random_below_biased(pq, rng);
    /* ⛔ lambda is the trapdoor - see the note above */
    var s = powmod_ct(t, lambda, N);

    var out = {
        pub: { N: N, s: s, t: t },
        sec: { p: a.p, q: b.p, lambda: lambda, phi: phi, pq: pq,
               p_factors: a.factors, q_factors: b.factors }
    };
    out.pk = out.pub;
    out.sk = out.sec;
    return out;
}

/**
 * The same parameters, sampled from TOUGH primes instead of strong ones.
 *
 * ==================== WHAT CHANGES ====================
 *
 * A strong prime is p = 2p' + 1 with p' prime. Finding one means finding a
 * prime AND having 2p'+1 be prime too, which by the prime number theorem
 * costs about n_rsa^2 / 2 primality tests.
 *
 * A TOUGH prime relaxes "p' is prime" to "(p-1)/2 has no small factors":
 *
 *     (p - 1)/2 = product of T primes of 2*ell bits each
 *
 * A pool of such primes is sampled ONCE and then reused across every
 * T-subset, so one pool yields (B choose T) candidates. That reuse is the
 * entire speedup - n_rsa tries rather than n_rsa^2 / 2.
 *
 * ⚠ RESAMPLING THE POOL PER CANDIDATE GIVES THE SLOW ALGORITHM WITH EXTRA
 *   STEPS, and it looks correct: same output, same tests pass. The tell is
 *   that the speedup stops widening with modulus size. Measured here, tough
 *   against safe: 529 vs 568 ms at 512 bits, 1205 vs 5935 at 768. A FLAT
 *   ratio means the pool is being resampled.
 *
 * ==================== WHY IT IS A SEPARATE FUNCTION ====================
 *
 * ⛔ THERE IS NO THEOREM THAT CGGMP21's PROOF SURVIVES THE SUBSTITUTION.
 *
 *   The paper's own words are "it appears that" the guarantees are identical
 *   "in every context we could think of". That is a cryptanalytic argument -
 *   Pollard's p-1 runs in O(2^(2*ell) * n log n) here, far worse than GNFS -
 *   and it is backed by an implementation from a team that ships this. It is
 *   not a reduction, and CGGMP21 is cited as a USER of strong primes rather
 *   than re-proven under tough ones.
 *
 *   So this is `keygen_rough`, not `keygen(bits, rng, {rough: true})`. An
 *   option disappears into a diff; a function name does not. Changing a
 *   security assumption should be a decision the caller makes, not one
 *   inherited from an upgrade.
 *
 * ⭐ AND IT REMOVES AN ASSUMPTION RATHER THAN ADDING ONE. Damgard-Fujisaki
 *   soundness normally needs strong RSA AND a small-order assumption. Here
 *   every subgroup of order above 2 has order at least 2^(2*ell) by
 *   construction, so small-order holds unconditionally and soundness reduces
 *   to strong RSA alone.
 *
 * @param {number} bits  modulus size; 2048 or more in production
 * @param {function} rng
 * @param {number} [ell=128]  half the size of each pool prime
 */
export function keygen_rough(bits, rng, ell) {
    return finish_task(keygen_rough_task(bits, rng, ell));
}

/**
 * keygen_rough as a task (commons/task.js). A step is one primality test -
 * a pool prime's candidate, or one subset's product - about 11 ms at 512
 * bits, the smallest unit the search has.
 */
export function keygen_rough_task(bits, rng, ell) {
    rng = require_rng('keygen_rough', rng);
    if (bits < 512) {
        throw new Error('ring_pedersen: modulus must be at least 512 bits');
    }
    var L = ell || 128;
    var half = bits >> 1;

    /*
     * ⚠ (p, q) = (3, 7) mod 8 IN SOME ORDER, and Algorithm 3 does not produce
     *   it - the paper adds it as a separate rejection in Algorithm 4. It is
     *   what makes the Jacobi symbol (2|N) equal -1, which Pi_mod's verifier
     *   checks:
     *
     *       p = 3 mod 8  =>  (2|p) = -1        p = 7 mod 8  =>  (2|p) = +1
     *       (3,7) -> -1   (3,3) -> +1   (7,7) -> +1
     *
     *   With an unconstrained pool each factor lands on 3 or 7 with about
     *   even odds, so this rejects about half the time. ⚠ REJECTING FAR MORE
     *   THAN HALF MEANS THE POOL IS CONSTRAINED mod 4 SOMEWHERE and every
     *   candidate is landing on 3 mod 8 - which yields a perfectly valid RSA
     *   modulus that passes every positive test and makes Pi_mod
     *   unsatisfiable.
     */
    function search() { return tough_prime_task(half, L, rng); }
    return then_task(search(), function (a) {
        return map_task(repeat_task(search, function (b) { return rough_partner(a, b); }, ROUGH_PARTNERS,
                                    'ring_pedersen: could not reach (3,7) mod 8 - if this ' +
                                    'ever fires, the prime pool is constrained mod 4'),
                        function (b) { return assemble_rough(a, b, rng); });
    });
}

/**
 * One tough prime: p = 2 * (product of T pool primes) + 1.
 *
 * ⚠ THE POOL IS NOT CONSTRAINED mod 4. An earlier reading of the paper had
 *   step 1 calling `Prime_1`, which samples primes = 1 mod 4 - and every
 *   product of such primes is 1 mod 4, so every p lands on 3 mod 8 and
 *   (3,7) becomes unreachable. Measured: 0 of 14 with the constraint, 5 of
 *   14 without.
 *
 *   `p = 3 mod 4` needs no constraint at all: the product of odd primes is
 *   odd, so p = 2(2k+1) + 1 = 4k + 3 always. What the pool's residue
 *   controls is p mod 8, not p mod 4.
 */
function tough_prime_task(bits, ell, rng) {
    var sh = tough_shape(bits, ell);
    var round = 0, pool = null, search = null, idx = null, found = null;
    return {
        /*
         * The two loops of the search, a primality test a step: fill a pool
         * of B primes (each a random_prime search), then try its T-subsets
         * in order; an exhausted pool means a fresh one, at most TOUGH_POOLS.
         */
        step: function () {
            if (found) { return true; }
            if (!pool) {
                if (round++ >= TOUGH_POOLS) { throw new Error('ring_pedersen: tough prime search exhausted'); }
                pool = [];
            }
            if (pool.length < sh.B) {
                if (!search) { search = random_prime_task(sh.each, rng, 8); }
                if (search.step()) { pool.push(search.result()); search = null; }
                return false;
            }
            if (!idx) { idx = first_subset(sh.T); }
            else if (!next_subset(idx, sh.T, sh.B)) { pool = null; idx = null; return false; }
            var c = subset_candidate(pool, idx);
            if (is_tough(c.p, bits, rng)) { found = c; }
            return found !== null;
        },
        result: function () { return found; }
    };
}

/*
 * ==================== THE PIECES OF THE SEARCH ====================
 *
 * ⭐ SHARED BY tough_prime AND the old keygen_rough_cb's tough(), which held the
 *   pool shape, the subset walk and the acceptance test twice: once as a
 *   loop and once as a chain of scheduled callbacks. They must agree
 *   exactly - the same rng must give the same prime on either path - and the
 *   two copies of the shape had already needed the same fix (the 2*ell pool
 *   width below) applied to each separately.
 */

/** How many pools a search samples before giving up. */
var TOUGH_POOLS = 400;

/**
 * T pool primes per candidate, each `each` bits, from a pool of B.
 *
 * ⛔ EACH POOL PRIME IS 2*ell BITS, as Algorithm 3 says. It used to be
 *   floor(bits / T), which is SMALLER than 2*ell whenever 2*ell does not
 *   divide bits: the product could then never reach `bits` (ell = 112 at 2048
 *   or 3072 always exhausted the search), and the factors would have been
 *   below the 2*ell that the toughness argument needs. With 2*ell-bit primes
 *   the prime may come out a little wider than `bits`.
 *
 * The pool is sampled ONCE and its subsets enumerated, which is what makes
 * this cheaper than resampling - see the note on keygen_rough. B is chosen so
 * there are comfortably more subsets than candidates expected to be needed;
 * the paper gives only (B choose T) > C*n_rsa and never fixes C.
 */
function tough_shape(bits, ell) {
    var T = Math.ceil(bits / (2 * ell));
    if (T < 2) { T = 2; }
    return { T: T, each: Math.max(2 * ell, Math.floor(bits / T)), B: T + 3 };
}

/* every T-subset, in a fixed (lexicographic) order so a run is reproducible */
function first_subset(T) {
    var idx = [];
    for (var k = 0; k < T; k++) { idx.push(k); }
    return idx;
}

/** Advance to the next T-subset of B in place; false when they are exhausted. */
function next_subset(idx, T, B) {
    var pos = T - 1;
    while (pos >= 0 && idx[pos] === B - T + pos) { pos--; }
    if (pos < 0) { return false; }
    idx[pos]++;
    for (var m = pos + 1; m < T; m++) { idx[m] = idx[m - 1] + 1; }
    return true;
}

/** p = 2 * (product of the subset) + 1, with the factors it was built from. */
function subset_candidate(pool, idx) {
    var prod = 1n, f = [];
    for (var j = 0; j < idx.length; j++) { prod *= pool[idx[j]]; f.push(pool[idx[j]]); }
    return { p: 2n * prod + 1n, factors: f };
}

function is_tough(p, bits, rng) {
    return p.toString(2).length >= bits && is_probable_prime(p, 8, rng);
}

/**
 * (p, q) = (3, 7) mod 8 in some order - the rejection Algorithm 4 adds and
 * Algorithm 3 does not produce. See keygen_rough.
 */
function mod8_pair(a, b) {
    var m1 = a.p % 8n, m2 = b.p % 8n;
    return (m1 === 3n && m2 === 7n) || (m1 === 7n && m2 === 3n);
}

/**
 * Is b an acceptable partner for a? (3,7) mod 8, and gcd(p-1, q-1) = 2.
 *
 * gcd(p-1, q-1) = 2 is required by Definition 3.10. The two pools are
 * independent, so a shared factor is astronomically unlikely - and unlikely
 * is not checked, so it is checked.
 *
 * ⚠ A SHARED FACTOR MEANS ANOTHER PARTNER. keygen_rough used to THROW
 *   ("the two prime pools share a factor") where the old callback form
 *   drew again. Drawing again is right: Algorithm 4 is a
 *   rejection sampler, and a pair that fails a condition is simply not
 *   output - throwing turned an unlucky draw into a failed key generation,
 *   and made the two paths answer the same rng differently.
 */
function rough_partner(a, b) {
    return mod8_pair(a, b) && gcd(a.p - 1n, b.p - 1n) === 2n;
}

/** How many partners keygen_rough tries for its first prime. */
var ROUGH_PARTNERS = 200;

/* =========================================================================
 * Pi_df* - the LARGE-CHALLENGE parameters proof.
 * eprint 2024/1950 section 5.7 Protocol 9, adapted there from [HLM25].
 * ======================================================================= */

/**
 * Prove s_i = t^(lambda_i) for one or more i, with a LARGE challenge.
 *
 * ==================== THE ONE DIFFERENCE ====================
 *
 *     Pi_df   (Protocol 8)   e in {0, 1}              soundness 1/2
 *     Pi_df*  (Protocol 9)   e in {0 .. 2^ell0 - 1}   soundness 2^-ell0
 *
 * A one-bit challenge needs hundreds of repetitions to reach negligible
 * soundness; a large one reaches it in a few. Measured on prove_params at
 * m = 80: 125 ms to prove and 86 ms to verify, and those repetitions are
 * what this removes.
 *
 * ⚠ THE MASK BOUND MOVES WITH THE CHALLENGE, and this is the easy thing to
 *   get wrong. alpha must hide e*lambda, which is now ell0 bits longer than
 *   in Pi_df. Sizing alpha the way Protocol 8 does leaves e*lambda uncovered
 *   and THE PROOF STILL VERIFIES for an honest prover - so a positive test
 *   sees nothing. The assertion below is the check that does.
 *
 * ==================== 🔴 IT IS NOT SOUND ON ITS OWN ====================
 *
 * ⛔ SOUNDNESS IS 1/omega + 2^-ell0 (Proposition 5.20), where
 *   omega = min{ i : s_i^i is in <t> }. The large challenge governs the
 *   SECOND term only, and the first is not bounded by anything this
 *   function sees.
 *
 * ⚠ MEASURED, twice, after two wrong explanations:
 *
 *   A prover holding s = -t^lambda grinds A until the Fiat-Shamir challenge
 *   comes out EVEN - at which point sigma^e = 1, so s^e is in <t> and
 *   z = alpha + e*lambda verifies. It takes about two attempts.
 *
 *   ⛔ THE MODULUS IS HONEST IN THAT ATTACK. The first note here said the
 *     attack used a maliciously chosen modulus and that a modulus proof
 *     would stop it. Both are false: -1 has order 2 in EVERY modulus, and a
 *     `verify_params_large_checked` written on that reasoning accepted the
 *     same forgery. It has been removed rather than left as reassurance.
 *
 * ⛔ AND REPETITION DOES NOT REMOVE IT - IT BOUNDS IT. k rounds give
 *   (1/omega + 2^-ell0)^k, which at omega = 2 is 2^-k. Under Fiat-Shamir a
 *   prover simply retries, so a subgroup of order omega costs about omega^k
 *   hashes (measured: omega = 2 forged in 2 tries at k = 1, 312 at k = 8).
 *   What k = 16 buys is that only omega below 2^(128/16) = 2^8 is
 *   affordable - the 2^ell0 guess of Theorem 6.4 with ell0 = ceil(ell/k) -
 *   and the protocol must then tolerate leaking a value mod omega, which is
 *   what eprint 2024/1950 does with nu_leak.
 *
 * ⭐ SO: THIS FUNCTION IS SOUND ONLY GIVEN A SEPARATE GUARANTEE THAT s LIES
 *   IN QR_N. t is a square, so <t> is inside QR_N, and -t^lambda is not -
 *   but deciding that needs the factorisation, and jacobi cannot do it:
 *   jacobi(s,N) and jacobi(-s,N) are both +1 when p = q = 3 mod 4.
 *
 *   ⚠ THIS LIBRARY DOES NOT HAVE THAT PROOF. Until it does, prefer
 *     prove_params - slower, and sound without it.
 *
 * ⭐ AND THERE IS A SECOND WAY TO BE A VALID CALLER, which is how the paper
 *   itself uses it: not by HAVING the guarantee, but by PRICING its absence.
 *
 *   eprint 2024/1950 does not establish that omega is large. Its simulator
 *   guesses it - "our simulator does not know omega_2... our strategy is to
 *   simply guess the order of the group" - and the 2^ell0 factor in Theorem
 *   6.4 IS that guess. So the protocol is sound with this proof inside it,
 *   because the loss is carried in its bound rather than assumed away.
 *
 *   ⛔ WHICH MEANS THE TWO USES ARE NOT INTERCHANGEABLE. A caller who knows
 *     omega is large gets soundness 2^-ell0. A caller who does not gets
 *     2^-ell0 only if it has accounted for a 2^ell0 loss somewhere - and a
 *     caller who has done neither gets one bit, measured above.
 *
 * ==================== 🔴 AND THE 2^ell0 IN THEOREM 6.4 ====================
 *
 * Theorem 6.4 carries a 2^ell0 factor, from the CHEATING SUBGROUP problem:
 * with a large challenge a prover can embed a small-order element sigma,
 * and commitments c = u^m t^r may then leak m mod ord(sigma). The paper's
 * simulator handles one case by GUESSING omega, which costs 2^ell0.
 *
 * ⛔ TOUGH PRIMES DO NOT REMOVE THIS, and the reasoning that says they do is
 *   backwards. keygen_rough guarantees OUR modulus has no small subgroups.
 *   The attack uses THEIRS - section 2.3.5 is explicit that the malformed
 *   tuple comes from the counterparty. A proof exists precisely to protect
 *   against a maliciously chosen modulus, so a property of ours cannot
 *   testify about theirs. That is an error in the direction of
 *   quantification, and it nearly went into this comment as fact.
 *
 * ==================== WHAT PROTOCOL 9 DOES NOT CHECK ====================
 *
 * ⚠ Protocol 8 verifies z is in range and Protocol 9 does not. That is the
 *   protocol as written in the paper, not an omission here. The verifier
 *   below takes an optional `max_bits` instead: not a soundness check, a
 *   size cap, so a prover cannot make the verifier exponentiate by a
 *   megabit-long z (measured in review: 15 s for one t^z).
 *
 * ⚠ THE PROOF IS "See [HLM25]". The paper does not prove Protocol 9; it
 *   refers to Haitner-Lindell-Makriyannis eprint 2025/081, which has not
 *   been read. That is also where the range check Protocol 8 has and
 *   Protocol 9 omits would be explained.
 *
 * ⭐ Claim 5.20 uses max over the s_i, not a product, so each s_i is judged
 *   on its own - which means reducing to a single secret is sound, and a
 *   Pi_df* proof with one secret proves exactly what Pi_df proves.
 *
 * @param {object} pub    { N, t } plus the s values, or use `secrets`
 * @param {Array}  secrets  the lambda_i, in the order the s_i are given
 * @param {Array}  esses    the s_i = t^(lambda_i)
 * @param {number} ell0     challenge bits; 32 in the paper's instantiation
 */
export function prove_params_large(pub, secrets, esses, rng, sid, ell0, nu, rounds) {
    require_sid('ring_pedersen', sid);
    rng = require_rng('prove_params_large', rng);
    if (!Array.isArray(secrets) || secrets.length === 0) {
        throw new TypeError('ring_pedersen: prove_params_large needs at least ' +
                            'one secret exponent');
    }
    if (!Array.isArray(esses) || esses.length !== secrets.length) {
        throw new TypeError('ring_pedersen: one s value per secret');
    }
    var L0 = ell0 || 32;
    if (L0 < 2) {
        throw new TypeError('ring_pedersen: ell0 must exceed 1 - a one-bit ' +
                            'challenge is Pi_df, and this is Pi_df*');
    }
    var NU = nu || 96;
    var R = rounds || 1;

    /*
     * alpha in +/-2^(ell0 + nu) * max_i 2^ceil(log lambda_i)  (Protocol 9):
     * it must cover e*lambda for every e below 2^ell0.
     */
    var maxbits = 0;
    for (var i = 0; i < secrets.length; i++) {
        var b = (secrets[i] < 0n ? -secrets[i] : secrets[i]).toString(2).length;
        if (b > maxbits) { maxbits = b; }
    }
    var alpha_bits = maxbits + L0 + NU;
    var bound = 1n << BigInt(alpha_bits);
    var alphas = [], A = [];
    for (var k = 0; k < R; k++) {
        var a = random_signed_below(bound, rng);
        alphas.push(a);
        /* ⛔ a Schnorr nonce: constant time over its PUBLIC range */
        A.push(powmod_signed_ct(pub.t, a, pub.N, alpha_bits + 1));
    }
    var e = large_challenge(pub, esses, A, sid, L0, secrets.length * R);
    var z = [];
    for (k = 0; k < R; k++) {
        var zk = alphas[k];
        for (var j = 0; j < secrets.length; j++) { zk += e[k * secrets.length + j] * secrets[j]; }
        z.push(zk);
    }
    return { A: A, z: z };
}


/**
 * ⛔ ell0 AND rounds ARE THE VERIFIER'S. They used to be read from the proof,
 *   which let a prover choose its own soundness - ell0 = 2 and one round.
 */
export function verify_params_large(pub, esses, proof, sid, ell0, rounds, max_bits) {
    require_sid('ring_pedersen', sid);
    var L0 = ell0, R = rounds;
    var cap = max_bits == null ? null : (1n << BigInt(max_bits));
    if (!(L0 > 1) || !(R >= 1)) { return false; }
    if (!proof || !Array.isArray(proof.A) || !Array.isArray(proof.z) ||
        proof.A.length !== R || proof.z.length !== R) { return false; }
    /* t must be a unit, or the equation is vacuous */
    if (gcd(pub.t, pub.N) !== 1n) { return false; }
    for (var i = 0; i < esses.length; i++) { if (gcd(esses[i], pub.N) !== 1n) { return false; } }
    var e = large_challenge(pub, esses, proof.A, sid, L0, esses.length * R);
    for (var k = 0; k < R; k++) {
        if (typeof proof.z[k] !== 'bigint' || typeof proof.A[k] !== 'bigint') { return false; }
        if (cap !== null && (!in_range(proof.z[k], cap))) { return false; }
        if (!unit_in(proof.A[k], pub.N)) { return false; }
        var lhs = powmod_signed(pub.t, proof.z[k], pub.N);
        if (lhs === null) { return false; }
        var rhs = proof.A[k] % pub.N;
        for (var j = 0; j < esses.length; j++) {
            rhs = (rhs * powmod(esses[j], e[k * esses.length + j], pub.N)) % pub.N;
        }
        if (lhs !== rhs) { return false; }
    }
    return true;
}

/**
 * Pi_df: the Damgard-Fujisaki parameters proof WITH SMALL EXPONENTS
 * (eprint 2024/1950 section 5.6, Protocol 8), repeated `rounds` times.
 *
 *   per round   A = t^alpha, alpha in +/-2^(2 ell + nu)
 *               e_1, e_2 in {0, 1}
 *               z = alpha + e_1 lambda_1 + e_2 lambda_2,  |z| <= 2^(2 ell + nu)
 *
 * Soundness 1/2 per round (Proposition 5.18), so ell rounds for 2^-ell. And
 * unlike Pi_df* it is ALSO A RANGE PROOF: an accepted proof shows
 * |lambda_i mod ord(t)| <= 2^(2 ell + nu + 1) (Claim 5.19) and leaves no
 * cheating subgroup - which is why the paper uses it for the SERVER's
 * long-lived parameters, under which every client commits.
 *
 * @param pub      { N, t }
 * @param secrets  [lambda_1, lambda_2], each below 2^(2 ell)
 * @param esses    [s_1, s_2] = t^lambda_i
 * @param o        { ell = 128, nu = 64, rounds = ell }
 */
export function prove_df_small(pub, secrets, esses, rng, sid, o) {
    require_sid('ring_pedersen', sid);
    rng = require_rng('prove_df_small', rng);
    o = o || {};
    var ell = o.ell || 128, NU = o.nu || 64, R = o.rounds || ell;
    var lim = 1n << BigInt(2 * ell);
    for (var i = 0; i < secrets.length; i++) {
        if (secrets[i] < 0n || secrets[i] >= lim) {
            throw new RangeError('ring_pedersen: Pi_df needs each lambda below 2^(2 ell)');
        }
    }
    var zb = 1n << BigInt(2 * ell + NU), wbits = 2 * ell + NU + 1;
    for (var attempt = 0; attempt < 64; attempt++) {
        var alphas = [], A = [];
        for (var k = 0; k < R; k++) {
            var a = random_signed_below(zb, rng);
            alphas.push(a);
            A.push(powmod_signed_ct(pub.t, a, pub.N, wbits));
        }
        var e = df_bits(pub, esses, A, sid, secrets.length * R);
        var z = [], fine = true;
        for (k = 0; k < R; k++) {
            var zk = alphas[k];
            for (var j = 0; j < secrets.length; j++) { if (e[k * secrets.length + j]) { zk += secrets[j]; } }
            /* an honest z leaves the range with probability about 2^(1-nu): start again */
            if (!in_range(zk, zb)) { fine = false; break; }
            z.push(zk);
        }
        if (fine) { return { A: A, z: z }; }
    }
    throw new Error('ring_pedersen: could not produce an in-range Pi_df response');
}

/** @return {boolean} */
export function verify_df_small(pub, esses, proof, sid, o) {
    require_sid('ring_pedersen', sid);
    o = o || {};
    var ell = o.ell || 128, NU = o.nu || 64, R = o.rounds || ell;
    if (!proof || !Array.isArray(proof.A) || !Array.isArray(proof.z) ||
        proof.A.length !== R || proof.z.length !== R) { return false; }
    if (gcd(pub.t, pub.N) !== 1n) { return false; }
    /* every s_j and A_k a unit, as Pi_df* already requires - a non-unit
       satisfies the relation in degenerate ways */
    for (var q = 0; q < esses.length; q++) { if (!unit_in(mod(esses[q], pub.N), pub.N)) { return false; } }
    for (q = 0; q < R; q++) { if (typeof proof.A[q] !== 'bigint' || !unit_in(proof.A[q], pub.N)) { return false; } }
    var zb = 1n << BigInt(2 * ell + NU);
    var e = df_bits(pub, esses, proof.A, sid, esses.length * R);
    for (var k = 0; k < R; k++) {
        var zk = proof.z[k], Ak = proof.A[k];
        if (typeof zk !== 'bigint' || typeof Ak !== 'bigint') { return false; }
        if (!in_range(zk, zb)) { return false; }
        var lhs = powmod_signed(pub.t, zk, pub.N);
        if (lhs === null) { return false; }
        var rhs = Ak % pub.N;
        for (var j = 0; j < esses.length; j++) {
            if (e[k * esses.length + j]) { rhs = rhs * (esses[j] % pub.N) % pub.N; }
        }
        if (lhs !== rhs) { return false; }
    }
    return true;
}

function df_bits(pub, esses, A, sid, count) {
    /* the two list lengths are framed: with only the total count bound,
       esses = [s1, s2], A = [a1] and esses = [s1], A = [s2, a1] hashed alike */
    var N = pub.N, parts = [N, mod(pub.t, N), BigInt(esses.length), BigInt(A.length)];
    for (var i = 0; i < esses.length; i++) { parts.push(mod(esses[i], N)); }
    for (i = 0; i < A.length; i++) { parts.push(mod(A[i], N)); }
    return fs_bits(fs_stream('cryptographic-primitives/ring-pedersen/df-small/v2', sid, parts), count);
}

/**
 * Pi_df*'s challenges: `count` values uniform in [0, 2^ell0).
 *
 * v3, on zk_bytes.fs_stream. v2 hashed the transcript to a seed and then
 * the seed and an index, one sha256 each, which capped ell0 at 256 bits (a
 * wider ell0 read past the digest and died with "Cannot convert undefined to
 * a BigInt"). Any ell0 works now. The transcript is v2's - ell0, N (whole,
 * where v2 had N mod N), t, the number of A, each A, each s.
 */
export function large_challenge(pub, esses, A, sid, ell0, count) {
    var N = pub.N;
    var As = Array.isArray(A) ? A : [A];
    var parts = [BigInt(ell0), N, mod(pub.t, N), BigInt(As.length)];
    for (var a = 0; a < As.length; a++) { parts.push(mod(As[a], N)); }
    for (var i = 0; i < esses.length; i++) { parts.push(mod(esses[i], N)); }
    var read = fs_stream('cryptographic-primitives/ring-pedersen/prm-star/v3', sid, parts);

    var out = [];
    for (var j = 0; j < count; j++) { out.push(fs_uint(read, ell0)); }
    return out;
}



/* =========================================================================
 * SampleDF - Algorithm 3 in full, steps 1 through 8.
 * ======================================================================= */

/**
 * The paper's own parameter generator, in the paper's own output shape.
 *
 * ⚠ THIS IS NOT keygen_rough UNDER ANOTHER NAME. The shapes differ:
 *
 *     keygen_rough   { N, s, t }           ONE base pair, ONE lambda
 *     sample_df      (N, v, u1, u2)        THREE elements, TWO lambdas
 *
 *   Algorithm 3 steps 6-8 sample v from QR_N and set (u1, u2) = (v^l1,
 *   v^l2). keygen_rough stops at step 5 and builds the two-base ring-Pedersen
 *   triple this library used before the paper arrived.
 *
 * ⭐ AND Pi_dlenc AND Pi_sig BOTH NEED THE THREE-BASE FORM. zk_dlenc.js says
 *   the caller supplies u1, u2 and v because keygen_rough could not - this
 *   is where they come from.
 *
 * ⚠ v MUST BE A QUADRATIC RESIDUE, which is why it is a square of a random
 *   unit rather than a random element. The paper bounds the chance that <v>
 *   is not all of QR_N by (n_rsa / 2l) * 2^-2l, which is why one sample
 *   suffices and no rejection loop is needed.
 *
 * @return {{pub: {N, v, u1, u2}, sec: {p, q, l1, l2, pq, p_factors, q_factors}}}
 */
export function sample_df(bits, rng, ell) {
    return finish_task(sample_df_task(bits, rng, ell));
}

/** sample_df as a task (commons/task.js): keygen_rough's steps, then steps 6-8. */
export function sample_df_task(bits, rng, ell) {
    return map_task(keygen_rough_task(bits, rng, ell), function (base) {
        return df_from_primes(base, bits, rng, ell || 128);
    });
}


/**
 * Steps 6-8 on top of a modulus that already satisfies steps 1-5.
 *
 * ⚠ THE EXPONENTS ARE DRAWN FROM [2^(2*ell)], NOT FROM THE GROUP ORDER.
 *   The order is pq and is secret; the paper's bound is on the range, and
 *   using the order here would be both unavailable to a caller checking the
 *   construction and a different distribution.
 */
function df_from_primes(base, bits, rng, ell) {
    /* `bits` is unused: the modulus is already fixed by `base`, and the
       parameter stays so this reads like the other builders in this file */
    var N = base.pub.N;
    var pq = base.sec.pq;

    /* v: a square of a random unit, so it lies in QR_N */
    var v = random_quadratic_residue(N, rng);

    var bound = 1n << BigInt(2 * ell);
    var l1 = random_below_biased(bound, rng);
    var l2 = random_below_biased(bound, rng);

    return {
        /* ⛔ l1 and l2 are the secret exponents this sampler exists to
           hide. ⚠ Sampled below 2^(2*ell), which may exceed |N|, so the
           width is passed explicitly. */
        pub: { N: N, v: v,
               u1: powmod_ct(v, l1, N, 2 * ell),
               u2: powmod_ct(v, l2, N, 2 * ell) },
        sec: { p: base.sec.p, q: base.sec.q, l1: l1, l2: l2, pq: pq,
               p_factors: base.sec.p_factors, q_factors: base.sec.q_factors }
    };
}
